  "Verify": "जाँचें",
  "Verifying and removing both reach the provider or the store, so both are audited and both count against the rate limit below. Removing cannot be undone from here — the old value is unreadable by design.": "सत्यापन और हटाना प्रदाता या स्टोर तक पहुँचते हैं, इसलिए दोनों का ऑडिट और दर सीमा में हिसाब होता है। हटाना यहाँ पूर्ववत नहीं होता; पुराना मान पढ़ा नहीं जा सकता।",
  "View analysis": "विश्लेषण देखें",
  "Write-only. The value is never returned by any endpoint, so it cannot be shown here or checked by eye — the last four characters and a fingerprint are what distinguish one key from another. Use": "केवल लिखने योग्य। कोई एंडपॉइंट मान लौटाता नहीं, इसलिए यहाँ दिखाया या देखकर जाँचा नहीं जा सकता। अंतिम चार अक्षर और फ़िंगरप्रिंट कुंजियाँ अलग पहचानते हैं। उपयोग करें",
  "Your message": "आपका संदेश",
