  "ui.total.time.not.by.counting.history.and.examination.bulle.4ca4c59a": "कुल समय, इतिहास और परीक्षण बिंदुओं की गिनती नहीं। अमेरिकी CPT मार्गदर्शन; इस टेनेंट की यूएई बिलिंग पर लागू नहीं।",
