  "Paediatric context: guardian as source, weight-based safety, age-specific ranges and consent rules apply.": "बाल संदर्भ: अभिभावक स्रोत, वजन आधारित सुरक्षा, आयु सीमाएँ और सहमति नियम लागू।",
  "Older adult context: falls, cognition, function, polypharmacy, caregiver context and goals of care are surfaced.": "वृद्ध संदर्भ: गिरना, संज्ञान, कार्यक्षमता, बहुदवा, देखभालकर्ता और देखभाल लक्ष्य दिखते हैं।",
  "Pregnancy context: gestational status, maternal and fetal warning signs, and medication and imaging safety are surfaced.": "गर्भावस्था संदर्भ: गर्भ स्थिति, मातृ-भ्रूण चेतावनी संकेत, दवा और इमेजिंग सुरक्षा दिखती हैं।",
  "Complex multimorbidity: problem reconciliation, competing risks, medication burden and care-plan ownership are prioritised.": "जटिल बहुरोग: समस्या मिलान, प्रतिस्पर्धी जोखिम, दवा भार और देखभाल योजना जिम्मेदारी प्राथमिक हैं।",
  "Paediatrics with a non-paediatric patient context. Valid for adolescent and transition clinics; confirm the age ranges and permissions are right for this service.": "गैर-बाल संदर्भ में बाल चिकित्सा। किशोर और संक्रमण क्लिनिक में मान्य; सेवा की आयु सीमाएँ और अनुमतियाँ पुष्टि करें।",
  "Paediatric context outside Paediatrics. The specialty must explicitly support paediatric practice, age ranges and consent handling.": "बाल चिकित्सा के बाहर बाल संदर्भ। विशेषज्ञता को बाल अभ्यास, आयु सीमाएँ और सहमति स्पष्ट रूप से समर्थित करनी चाहिए।",
  "Pregnancy with Orthopaedics: medication and imaging safety considerations apply. This is a prompt, not a reason to withhold clinically indicated care.": "गर्भावस्था और अस्थि रोग: दवा और इमेजिंग सुरक्षा लागू। यह संकेत है, आवश्यक देखभाल रोकने का कारण नहीं।",
  "Pregnancy with Psychiatry: perinatal mental-health pathways and medication-safety considerations apply.": "गर्भावस्था और मनोरोग: प्रसवकालीन मानसिक स्वास्थ्य और दवा सुरक्षा लागू।",
  "Obstetrics & Gynaecology with a paediatric context may be adolescent gynaecology. Age, consent and privacy rules for the jurisdiction apply.": "बाल संदर्भ में स्त्री-प्रसूति किशोर स्त्री रोग हो सकता है। क्षेत्र के आयु, सहमति और गोपनीयता नियम लागू।",
